import numpy as np

def count_roots(alpha, beta):
    # Polynomial: 3w^4 - 4(alpha+beta)w^3 + 6*alpha*beta*w^2 - (alpha^2 * beta^2) = 0
    coeffs = [3, -4*(alpha+beta), 6*alpha*beta, 0, -(alpha**2 * beta**2)]
    roots = np.roots(coeffs)
    # Count real roots with some tolerance
    real_roots = roots[np.isreal(roots)].real
    # Check for distinctness
    unique_roots = []
    for r in real_roots:
        if not any(np.isclose(r, ur) for ur in unique_roots):
            unique_roots.append(r)
    return len(unique_roots)

# Test some values of alpha and beta with beta > alpha > 0
results = set()
for alpha in np.linspace(0.1, 5, 20):
    for beta in np.linspace(alpha + 0.1, 10, 20):
        results.add(count_roots(alpha, beta))

print(f"Results for different alpha, beta: {results}")

